param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$OutputDirectory,[int]$TextScale=100,[int]$Width=1000,[int]$Height=650,[switch]$ThumbnailOnly,[switch]$FavoriteOnly,[switch]$ViewerBackOnly)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public static class ManageNative{[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("user32.dll")]public static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint f);}'
$output=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $output){throw 'Fresh output required'};[IO.Directory]::CreateDirectory($output)|Out-Null
$data=Join-Path $output 'isolated-data';$stateFile=Join-Path $data 'window-state.json';$checks=0;$process=$null
function State{for($attempt=0;$attempt -lt 10;$attempt++){try{$stream=[IO.FileStream]::new($stateFile,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));$reader=[IO.StreamReader]::new($stream);try{$value=$reader.ReadToEnd()|ConvertFrom-Json}finally{$reader.Dispose()};$script:hasState=$true;return $value}catch{Start-Sleep -Milliseconds 10}};if($script:hasState){throw 'Own diagnostic state could not be read'};return $null}

function Await([scriptblock]$test,[string]$name){$end=[DateTime]::UtcNow.AddSeconds(40);do{$matched=$false;try{$matched=&$test}catch{$transient=$false;$cause=$_.Exception;for($depth=0;$depth -lt 8 -and $cause;$depth++){if($cause.GetType().FullName -eq 'System.Windows.Automation.ElementNotAvailableException'){$transient=$true;break};$cause=$cause.InnerException};if(-not $transient){throw}};if($matched){return};if($process.HasExited){throw ('EXIT '+$name)};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow -lt $end);throw ('TIMEOUT '+$name)}

function Checkpoint([string]$name){Await {$s=State;return -not $s.workspace.management.loading -and -not $s.workspace.management.writing -and $s.revision -eq $s.captureRevision} ('capture '+$name);$s=State;@{name=$name;capture=$s.captures[-1];revision=$s.revision}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $output 'checkpoints.jsonl')}
function Check([bool]$value,[string]$name){if(-not $value){throw ('MANAGEMENT_FAIL '+$name)};$script:checks++}
function SelectFirstModel{
 Await {$list=Find 'ManageList';if(-not $list -or -not $list.Current.IsEnabled){return $false};$script:firstModel=$list.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::ListItem));return $null -ne $script:firstModel} 'first model card realized'
 $script:firstModel.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select()
 Await {$null -ne (Find 'ManageSelectedModel')} 'selected model inspector'
}
try{
 $start=[Diagnostics.ProcessStartInfo]::new([IO.Path]::GetFullPath($Executable));$start.UseShellExecute=$false;$start.WindowStyle='Hidden';$start.Arguments='--data-dir "'+$data+'" --diagnostics --capture --text-scale '+$TextScale
 $process=[Diagnostics.Process]::Start($start);Await {(State).ready -and (State).revision -eq (State).captureRevision} 'ready';$root=[Windows.Automation.AutomationElement]::FromHandle([IntPtr][long](State).hwnd);[ManageNative]::SetWindowPos([IntPtr][long](State).hwnd,[IntPtr]::Zero,0,0,$Width,$Height,0x14)|Out-Null
 function Find([string]$id){return $root.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::AutomationIdProperty,$id))}
 function Reach([string]$id){Await {$e=Find $id;if(-not $e -or -not $e.Current.IsEnabled){return $false};$rect=$e.Current.BoundingRectangle;$minimum=if($id.StartsWith("Nav") -and $id -ne "NavSettings"){48}else{0};$parent=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($e);$ancestors=@();for($level=0;$level -lt 16 -and $parent;$level++){if($parent.Current.ProcessId -ne $process.Id){break};$sp=$null;if($parent.TryGetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern,[ref]$sp)){$ancestors+=,@($parent,$sp)};if($parent.Current.NativeWindowHandle -eq $root.Current.NativeWindowHandle -and $parent.Current.NativeWindowHandle -ne 0){break};$parent=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($parent)}
  for($ancestorIndex=$ancestors.Count-1;$ancestorIndex -ge 0;$ancestorIndex--){$pair=$ancestors[$ancestorIndex];$scroll=$pair[0];$pattern=$pair[1];$viewport=$scroll.Current.BoundingRectangle;$ownBounds=$root.Current.BoundingRectangle;$viewport.Intersect($ownBounds);if($rect.Height -gt 0 -and $rect.Top -ge $viewport.Top-1 -and $rect.Bottom -le $viewport.Bottom+1 -and $rect.Height -ge [Math]::Max(1,$minimum-1)){continue};if($pattern.Current.VerticallyScrollable){$direction=if($rect.Height -gt 0 -and ($rect.Top -lt $viewport.Top -or ($rect.Height -lt $minimum-1 -and $rect.Top -le $viewport.Top+1))){[Windows.Automation.ScrollAmount]::SmallDecrement}else{[Windows.Automation.ScrollAmount]::SmallIncrement};if($e.Current.IsOffscreen -and $pattern.Current.VerticalScrollPercent -ge 99){$pattern.SetScrollPercent(-1,0)}else{$pattern.Scroll([Windows.Automation.ScrollAmount]::NoAmount,$direction)}};return $false};$bounds=$root.Current.BoundingRectangle;$script:reachedElement=$e;return -not $e.Current.IsOffscreen -and $rect.Height -ge [Math]::Max(1,$minimum-1) -and $rect.Top -ge $bounds.Top -and $rect.Bottom -le $bounds.Bottom} ('fully reachable '+$id)}

 function Click([string]$id){Reach $id;$script:reachedElement.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();$script:checks++;if($id.StartsWith('Nav')){$page=$id.Substring(3);Await {$s=State;return $s.workspace.page -eq $page -and -not $s.workspace.management.loading -and $s.revision -eq $s.captureRevision} ('settled '+$page)}}
 function SetText([string]$id,[string]$value){Reach $id;$e=Find $id;$e.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).SetValue($value)}
 Click 'GalleryOpen';Await {(State).workspace.gallery.itemCount -eq 120 -and -not (State).workspace.gallery.loading} 'gallery'
 if($ThumbnailOnly){Click 'NavSettings';Await {$e=Find 'ManagePreferenceThumbnail';return $e -and $e.Current.IsEnabled -and -not (State).workspace.management.loading} 'thumbnail preference';Reach 'ManagePreferenceThumbnail';(Find 'ManagePreferenceThumbnail').GetCurrentPattern([Windows.Automation.RangeValuePattern]::Pattern).SetValue(1200);Click 'ManageSavePreferences';Await {(State).workspace.gallery.preferredThumbnailSize -eq 1200 -and -not (State).workspace.management.writing} 'applied';Click 'NavGallery';Click 'GalleryRefresh';Await {(State).workspace.gallery.thumbnailActive -eq 0 -and (State).workspace.gallery.thumbnailQueue -eq 0 -and ((State).workspace.gallery.thumbnailCompleted -gt 0 -or (State).workspace.gallery.thumbnailFailed -gt 0)} 'decode finished';Check ((State).workspace.gallery.thumbnailCompleted -gt 0 -and (State).workspace.gallery.thumbnailFailed -eq 0) '1200 thumbnails actually decode';Click 'ClosePreview';$process.WaitForExit(30000)|Out-Null;Write-Output ('THUMBNAIL_PASSED '+$checks);return}
 if($ViewerBackOnly){(Find 'GalleryImage1').GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();(Find ('GalleryImage'+(State).workspace.gallery.currentId)).SetFocus();[ManageNative]::PostMessage([IntPtr][long](State).hwnd,0x100,[IntPtr]13,[IntPtr]0)|Out-Null;[ManageNative]::PostMessage([IntPtr][long](State).hwnd,0x101,[IntPtr]13,[IntPtr]0)|Out-Null;Await {(State).workspace.viewer.displayedId -eq 1} 'viewer current';Click 'ViewerBack';Await {-not (State).workspace.viewer.open -and (State).revision -eq (State).captureRevision} 'viewer back';$capture=Join-Path $data @((State).captures)[-1];$colors=(& (Join-Path $PSScriptRoot '../../../.venv-build/Scripts/python.exe') -c 'from PIL import Image;import sys;im=Image.open(sys.argv[1]);print(len(im.crop((0,0,180,im.height)).getcolors(180*im.height)))' $capture);Check ([int]$colors -gt 10) 'own captured navigation is visibly restored after viewer';Click 'ClosePreview';$process.WaitForExit(30000)|Out-Null;return}
 if($FavoriteOnly){(Find 'GalleryImage1').GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();Await {(State).workspace.gallery.currentId -eq 1} 'favorite target';Click 'GalleryHeart1';Await {$s=State;return $s.workspace.gallery.currentFavorite -and -not $s.workspace.gallery.annotationWriting -and -not $s.workspace.gallery.loading -and $s.revision -eq $s.captureRevision} 'favorite settled';Check ((State).workspace.gallery.currentId -eq 1 -and (Find 'GalleryHeart1').Current.Name -eq '取消收藏') 'favorite preserves current image';Click 'ClosePreview';$process.WaitForExit(30000)|Out-Null;return}
 Click 'NavTags';Await {$s=State;return $s.workspace.management.tagCount -eq 2 -and -not $s.workspace.management.loading -and $s.revision -eq $s.captureRevision} 'real management page'
 Check ($null -ne (Find 'ManageTagSave')) 'semantic editor exists'
 Check (-not (Find 'ManageClassify').Current.IsEnabled) 'no invented inference without installed model or selection'
 Click 'ManageTagNew';SetText 'ManageTagName' '合成天空';SetText 'ManageTagDescription' 'abc';Click 'ManageTagSave'
 Await {(State).workspace.management.uncertain -or (Find 'ManageStatus').Current.Name.Contains('判定描述')} 'invalid definition feedback'
 Check ((Find 'ManageStatus').Current.Name.Contains('判定描述') -and (State).workspace.management.tagCount -eq 2) 'invalid description rejected inline without submission'
 SetText 'ManageTagDescription' 'a clear blue sky with clouds';Click 'ManageTagSave'
 Await {(State).workspace.management.tagCount -eq 3 -and -not (State).workspace.management.writing} 'saved definition'
 Await {(State).revision -eq (State).captureRevision -and (Find 'ManageTagName').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value -eq '合成天空'} 'saved definition layout'
 Check ((Find 'ManageTagName').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value -eq '合成天空') 'saved category remains selected';Checkpoint 'saved-category'
 Click 'NavModels';Await {$null -ne (Find 'ManagePickModels')} 'models'
 $models=Join-Path $output 'synthetic-models';[IO.Directory]::CreateDirectory($models)|Out-Null;[IO.File]::WriteAllBytes((Join-Path $models '合成模型 SDXL.safetensors'),[Text.Encoding]::UTF8.GetBytes('inert synthetic weight never deserialize'))
 Click 'ManageShowModelPath';SetText 'ManageModelPath' $models;Click 'ManageAddModelRoot';Await {(State).workspace.management.rootCount -eq 1} 'directory added'
 Await {(State).workspace.management.modelCount -eq 1 -and -not (State).workspace.management.loading -and -not (State).workspace.management.writing} 'add automatically indexes model'
 Click 'NavJobs';Await {(State).workspace.management.jobCount -gt 0} 'durable job visible'
 Await {(State).workspace.management.activeJobs -eq 0} 'scan finished'
 Click 'NavModels';Await {(State).workspace.management.modelCount -eq 1} 'scanned inventory'
 Check ([IO.File]::ReadAllText((Join-Path $models '合成模型 SDXL.safetensors')) -eq 'inert synthetic weight never deserialize') 'weight unchanged'
 # Coalesce navigation during in-flight reads and retain the latest model scope.
 for($cycle=0;$cycle -lt 6;$cycle++){foreach($nav in @('NavJobs','NavTags','NavModels')){(Find $nav).GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke()}}
 Await {$s=State;return $s.workspace.page -eq 'Models' -and -not $s.workspace.management.loading -and $s.workspace.management.modelCount -eq 1 -and $s.revision -eq $s.captureRevision} 'latest page after overlapping reads';Check ($null -ne (Find 'ManageModelSearch')) 'destination form loaded without manual refresh'
 Click 'ManageRefresh';Await {-not (State).workspace.management.loading} 'model refresh settled';SetText 'ManageModelSearch' 'no-synthetic-model-matches';Click 'ManageSearchModels';Await {-not (State).workspace.management.loading -and (State).workspace.management.modelCount -eq 0} 'latest search wins over old refresh';Check ($null -eq (Find 'ManageModelDetails')) 'no stale model actions after empty scope';SetText 'ManageModelSearch' '';Click 'ManageSearchModels';Await {-not (State).workspace.management.loading -and (State).workspace.management.modelCount -eq 1} 'model scope restored'
 # Inspect the single inert model without hashing or real network.
 SelectFirstModel
 Click 'ManageModelDetails';Click 'ManageCandidateImages';Await {(State).workspace.management.linkedTotal -eq 66 -and (State).workspace.management.linkedCount -eq 60} '60 bounded name candidates'
 Check ((State).workspace.management.associationMode -eq 'candidate') 'candidate evidence distinction';Checkpoint 'candidate-first-page'
 Click 'ManageLinkedImage1';Await {(State).workspace.viewer.open -and (State).workspace.viewer.displayedId -eq 1} 'candidate opens native viewer';Check ((State).workspace.viewer.total -eq 66) 'viewer retains candidate scope';Click 'ViewerBack';Await {(State).workspace.management.associationMode -eq 'candidate' -and -not (State).workspace.viewer.open} 'back preserves model candidate mode'
 Click 'ManageLinkedNext';Await {(State).workspace.management.linkedCount -eq 6} 'candidate tail page';Checkpoint 'candidate-next-page'
 Click 'ManageModelReturn';Click 'ManageRegistry';SetText 'ManageRegistryMatch' 'synthetic-native-model';Click 'ManageRegistrySave';Await {(State).workspace.management.registryCount -eq 1} 'exact rule saved';Checkpoint 'exact-rule'
 Click 'ManageRegistryReturn';Click 'ManageDiagnosis';Await {$null -ne (Find 'ManageDiagnosisReturn')} 'leaf diagnostic';Check (-not (State).workspace.management.uncertain) 'read diagnostic has no write';Click 'ManageDiagnosisReturn'
 Click 'NavSettings';SetText 'ManageApiToken' 'synthetic-native-token-0123456789';(Find 'ManageRememberCredential').GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern).Toggle();Click 'ManageSaveCredential';Await {(State).workspace.management.credentialConfigured -and (State).workspace.management.credentialRemembered} 'DPAPI save presence only'
 # Never read PasswordBox.Value or clipboard.
 Click 'ManageClearCredential';Await {-not (State).workspace.management.credentialConfigured} 'credential cleared without network'
 Click 'NavGallery';Await {$null -ne (Find 'GalleryImage1')} 'gallery retained';(Find 'GalleryImage1').GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();Await {(State).workspace.gallery.currentId -eq 1} 'selected'
 Click 'GalleryEditTags';Await {(State).workspace.management.selectionCount -eq 1 -and -not (State).workspace.management.loading -and (State).workspace.management.tagCount -eq 3} 'selected label scope';$select=$null;Await {$tagList=Find 'ManageList';if(-not $tagList){return $false};$tagChoice=$tagList.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::NameProperty,'合成天空'));while($tagChoice){$pattern=$null;if($tagChoice.TryGetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern,[ref]$pattern)){$script:tagSelect=$pattern;return $true};$tagChoice=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($tagChoice)};$scroll=$tagList.GetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern);if($scroll.Current.VerticallyScrollable){$scroll.Scroll([Windows.Automation.ScrollAmount]::NoAmount,[Windows.Automation.ScrollAmount]::SmallIncrement)};return $false} 'virtualized custom category';$script:tagSelect.Select();Check ($null -ne $script:tagSelect) 'custom semantic category selected';Click 'ManageLabelPreview';Await {(State).workspace.management.labelSnapshotReady} 'label preview'
 Click 'ManageConfirmTag';Await {-not (State).workspace.management.writing -and (State).workspace.management.feedback -like '*完成*'} 'manual include'
 # Explicit synthetic import must refresh count and directory choices.
 Click 'NavGallery';Click 'GalleryImportPathToggle';$import=Join-Path $output 'synthetic-import';[IO.Directory]::CreateDirectory($import)|Out-Null;Copy-Item -LiteralPath (Join-Path (Split-Path -Parent $Executable) 'Assets/Stage2/alpine.png') -Destination (Join-Path $import 'imported.png')
 SetText 'GalleryImportPath' $import;Click 'GalleryImportStart';Await {(State).workspace.page -eq 'Jobs' -and (State).workspace.management.activeJobs -eq 0} 'import task safe completion';Click 'NavGallery';Click 'GalleryRefresh';Await {(State).workspace.gallery.total -eq 132} 'import refreshed index'
 Click 'NavJobs';Click 'ManageRefresh';Check ((State).workspace.management.jobCount -ge 1) 'same persisted jobs';Checkpoint 'persistent-tasks'
 Click 'NavSettings'
 # Preferences must decode the advertised high resolution, not just persist a number.
 Await {$e=Find 'ManagePreferenceThumbnail';return $e -and $e.Current.IsEnabled -and -not (State).workspace.management.loading} 'thumbnail preference';Reach 'ManagePreferenceThumbnail';(Find 'ManagePreferenceThumbnail').GetCurrentPattern([Windows.Automation.RangeValuePattern]::Pattern).SetValue(1200);Click 'ManageSavePreferences';Await {-not (State).workspace.management.writing -and (State).workspace.gallery.preferredThumbnailSize -eq 1200} 'preference applied';Click 'NavGallery';Click 'GalleryRefresh';Await {(State).workspace.gallery.thumbnailCompleted -gt 0 -and (State).workspace.gallery.thumbnailActive -eq 0 -and (State).workspace.gallery.thumbnailQueue -eq 0} 'high resolution thumbnails decoded';Check ((State).workspace.gallery.thumbnailFailed -eq 0) 'no high resolution decode failures';Check ((State).workspace.gallery.decodedBytes -le 67108864) '64 MiB cache budget'
 Click 'ClosePreview';Check ($process.WaitForExit(30000) -and $process.ExitCode -eq 0) 'safe close'
 @{result='passed';count=$checks;state=(State);syntheticOnly=$true}|ConvertTo-Json -Depth 14|Set-Content -LiteralPath (Join-Path $output 'management-window-report.json');Write-Output ('MANAGEMENT_WINDOW_PASSED '+$checks)
}catch{(State)|ConvertTo-Json -Depth 14|Set-Content -LiteralPath (Join-Path $output 'failure-state.json');($_|Format-List * -Force|Out-String)|Set-Content -LiteralPath (Join-Path $output 'exception.txt');throw}finally{if($process -and -not $process.HasExited){$process.CloseMainWindow()|Out-Null;$process.WaitForExit(30000)|Out-Null}}
